        for (int r = 0; r < n; ++r)
        {
            for (int c = 0; c < n / 2; ++c)
            {
                int saved = matrix[r][c];
                matrix[r][c] = matrix[r][n - 1 - c];
                matrix[r][n - 1 - c] = saved;
            }
        }
