    public int FindMagicIndex(int[] values, bool distinctValues)
    {
        if (distinctValues)
        {
            int low = 0, high = values.Length - 1;
            while (low <= high)
            {
                int middle = low + (high - low) / 2;
                if (values[middle] == middle)
                    return middle;
                if (values[middle] > middle)
                    high = middle - 1;
                else
                    low = middle + 1;
            }
            return -1;
        }
