        {
            if (low > high)
                return -1;
            int middle = low + (high - low) / 2, value = values[middle];
            if (value == middle)
                return middle;
            int left = Search(low, Math.Min(middle - 1, value));
            return left != -1 ? left : Search(Math.Max(middle + 1, value), high);
        }
        return Search(0, values.Length - 1);
    }
}

