{
    public int SparseSearch(string[] words, string target)
    {
        if (target.Length == 0)
            return -1;
        int low = 0, high = words.Length - 1;
        while (low <= high)
        {
            int middle = low + (high - low) / 2;
            if (words[middle].Length == 0)
            {
                int left = middle - 1, right = middle + 1;
                while (true)
                {
