                        dp[end] = Math.Max(dp[end], dp[start] + 1);
            if (dp[word.Length] >= 2 &&
                (word.Length > best.Length ||
                 (word.Length == best.Length && StringComparer.Ordinal.Compare(word, best) < 0)))
                best = word;
        }
        return best;
    }
}

